import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"卡密激活","description":"","frontmatter":{},"headers":[],"relativePath":"self-service/license.md","filePath":"self-service/license.md"}'),r={name:"self-service/license.md"};function o(s,a,h,n,d,c){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="卡密激活" tabindex="-1">卡密激活 <a class="header-anchor" href="#卡密激活" aria-label="Permalink to &quot;卡密激活&quot;">​</a></h1><p>卡密激活页面用于使用卡密激活会员资格。</p><h2 id="激活流程" tabindex="-1">激活流程 <a class="header-anchor" href="#激活流程" aria-label="Permalink to &quot;激活流程&quot;">​</a></h2><h3 id="步骤-1-获取卡密" tabindex="-1">步骤 1：获取卡密 <a class="header-anchor" href="#步骤-1-获取卡密" aria-label="Permalink to &quot;步骤 1：获取卡密&quot;">​</a></h3><p>从应用管理员或渠道商获取卡密。</p><h3 id="步骤-2-访问激活页面" tabindex="-1">步骤 2：访问激活页面 <a class="header-anchor" href="#步骤-2-访问激活页面" aria-label="Permalink to &quot;步骤 2：访问激活页面&quot;">​</a></h3><ul><li>通过应用管理员提供的链接访问</li><li>或访问 <code>/license?id=应用ID</code></li></ul><h3 id="步骤-3-输入卡密" tabindex="-1">步骤 3：输入卡密 <a class="header-anchor" href="#步骤-3-输入卡密" aria-label="Permalink to &quot;步骤 3：输入卡密&quot;">​</a></h3><ol><li>在输入框中输入卡密</li><li>点击「激活」按钮</li></ol><h3 id="步骤-4-完成激活" tabindex="-1">步骤 4：完成激活 <a class="header-anchor" href="#步骤-4-完成激活" aria-label="Permalink to &quot;步骤 4：完成激活&quot;">​</a></h3><ul><li>激活成功后会员自动生效</li><li>可在 <a href="/docs/portal/membership.html">会员信息</a> 查看详情</li></ul><h2 id="卡密格式" tabindex="-1">卡密格式 <a class="header-anchor" href="#卡密格式" aria-label="Permalink to &quot;卡密格式&quot;">​</a></h2><p>卡密通常为以下格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XXXX-XXXX-XXXX-XXXX</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q-提示卡密无效" tabindex="-1">Q: 提示卡密无效？ <a class="header-anchor" href="#q-提示卡密无效" aria-label="Permalink to &quot;Q: 提示卡密无效？&quot;">​</a></h3><p>A: 请确认卡密输入正确，或联系管理员确认卡密状态。</p><h3 id="q-提示卡密已使用" tabindex="-1">Q: 提示卡密已使用？ <a class="header-anchor" href="#q-提示卡密已使用" aria-label="Permalink to &quot;Q: 提示卡密已使用？&quot;">​</a></h3><p>A: 该卡密已被其他账号使用，请联系管理员。</p><h3 id="q-激活后会员没有生效" tabindex="-1">Q: 激活后会员没有生效？ <a class="header-anchor" href="#q-激活后会员没有生效" aria-label="Permalink to &quot;Q: 激活后会员没有生效？&quot;">​</a></h3><p>A: 请刷新页面或重新登录查看。</p><h3 id="q-卡密有有效期吗" tabindex="-1">Q: 卡密有有效期吗？ <a class="header-anchor" href="#q-卡密有有效期吗" aria-label="Permalink to &quot;Q: 卡密有有效期吗？&quot;">​</a></h3><p>A: 是的，请在有效期内使用。</p>',23)])])}const q=e(r,[["render",o]]);export{u as __pageData,q as default};
